/* ---------- theme ---------- */
function applyTheme(mode) { try { localStorage.mm_theme = mode; } catch (e) {} const sys = matchMedia('(prefers-color-scheme: light)').matches; document.documentElement.dataset.theme = mode === 'system' ? (sys ? 'light' : 'dark') : mode; }
