/* ---------- chrome ---------- */
const NAV = [['overview', 'grid', 'Overview'], ['positions', 'layers', 'Positions'], ['sessions', 'pulse', 'Sessions'], ['brain', 'brain', 'Brain'], ['journal', 'book', 'Journal'], ['config', 'sliders', 'Config']];
